// Vector tables. Never generated by drizzle-kit: ensureVectorSchema applies VECTOR_DDL
// only when the capability check passes, so keyword-only databases never see the type.

import { index, pgTable, text, timestamp, vector, primaryKey } from "drizzle-orm/pg-core";

export const VECTOR_DIMS = 1536;

export const chunkEmbeddings = pgTable("chunk_embeddings", {
  chunkId: text("chunk_id").primaryKey(),
  userId: text("user_id").notNull(),
  model: text("model").notNull(),
  embedding: vector("embedding", { dimensions: VECTOR_DIMS }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, (t) => [index("chunk_embeddings_user_model_idx").on(t.userId, t.model)]);

export const embeddingCache = pgTable("embedding_cache", {
  textHash: text("text_hash").notNull(),
  model: text("model").notNull(),
  embedding: vector("embedding", { dimensions: VECTOR_DIMS }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, (t) => [primaryKey({ columns: [t.textHash, t.model] })]);

export const VECTOR_DDL = [
  `create table if not exists chunk_embeddings (
     chunk_id text primary key,
     user_id text not null,
     model text not null,
     embedding vector(${VECTOR_DIMS}) not null,
     created_at timestamptz not null default now())`,
  `create index if not exists chunk_embeddings_hnsw_idx on chunk_embeddings using hnsw (embedding vector_cosine_ops) with (m = 16, ef_construction = 64)`,
  `create index if not exists chunk_embeddings_user_model_idx on chunk_embeddings (user_id, model)`,
  `create table if not exists embedding_cache (
     text_hash text not null,
     model text not null,
     embedding vector(${VECTOR_DIMS}) not null,
     created_at timestamptz not null default now(),
     primary key (text_hash, model))`,
];
